<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment receipt {{ $payment->id }}</title><style>body{font:16px/1.7 system-ui;color:#183332;background:#f5f7f4;padding:25px}main{max-width:720px;margin:auto;padding:30px;background:white;border-radius:18px}dl{display:grid;grid-template-columns:1fr 2fr;gap:15px}dd{margin:0;overflow-wrap:anywhere}button,a{font:inherit;padding:10px;color:inherit}@media print{button,a{display:none}body{padding:0}}</style></head><body><main><p>USP EDUCATION · PAYMENT RECEIPT</p><h1>Payment received</h1><dl>
<dt>Receipt</dt><dd>EDU-{{ $payment->id }}</dd><dt>Student</dt><dd>{{ $payment->enrollment->student->name }}</dd><dt>Course</dt><dd>{{ $payment->enrollment->batch->course->title }}</dd><dt>Batch</dt><dd>{{ $payment->enrollment->batch->name }}</dd><dt>Amount</dt><dd>{{ $payment->currency }} {{ number_format($payment->amount_minor / 100,2) }}</dd><dt>Method</dt><dd>{{ str_replace('_',' ',$payment->method) }}</dd><dt>Reference</dt><dd>{{ $payment->reference }}</dd><dt>Verified</dt><dd>{{ $payment->reviewed_at?->format('d M Y H:i T') ?? 'Approved' }}</dd></dl><button onclick="window.print()">Print / save PDF</button><a href="{{ auth()->user()->is_admin ? '/admin/education/enrollments/'.$payment->course_enrollment_id : '/learn/'.$payment->course_enrollment_id }}">Back to enrollment</a></main></body></html>
